    def default_func(obj):
        if hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes, Mapping)):
            try:
                items = list(obj)
                return items
            except Exception:
                pass
        for type_, converter in JSON_CONVERTOR.items():
            if isinstance(obj, type_):
                return converter(obj)
        if default_mapping:
            for type_, converter in default_mapping.items():
                if isinstance(obj, type_):
                    return converter(obj)
        raise TypeError(f"We do not know how to convert {repr(obj)} of type {type(obj)} for json serialization. "
                        f"Please pass the default_mapping parameter with proper mapping of the object to a basic python type.")
    return default_func
